 * side's own lines across the full span its changes cover.
 */
function sideLinesFor(sideChanges, sideDoc, base, region) {
  if (sideChanges.length === 0) return base.slice(region.baseStart, region.baseEnd)
  const first = sideChanges[0]
  const last = sideChanges[sideChanges.length - 1]
  const prefix = base.slice(region.baseStart, first.baseStart)
  const middle = sideDoc.slice(first.sideStart, last.sideEnd)
  const suffix = base.slice(last.baseEnd, region.baseEnd)
  return prefix.concat(middle, suffix)
}

function resolveRegion(region, base, mine, theirs) {
  if (region.changes.length === 1) {
    const change = region.changes[0]
    const doc = change.side === 'mine' ? mine : theirs
    return { type: change.side, lines: doc.slice(change.sideStart, change.sideEnd) }
  }

  const mineChanges = region.changes.filter(change => change.side === 'mine')
  const theirsChanges = region.changes.filter(change => change.side === 'theirs')
  const mineLines = sideLinesFor(mineChanges, mine, base, region)
  const theirsLines = sideLinesFor(theirsChanges, theirs, base, region)
  const baseLines = base.slice(region.baseStart, region.baseEnd)

  if (arraysEqual(mineLines, theirsLines)) return { type: 'both', lines: mineLines }
  if (arraysEqual(mineLines, baseLines)) return { type: 'theirs', lines: theirsLines }
  if (arraysEqual(theirsLines, baseLines)) return { type: 'mine', lines: mineLines }
  return { type: 'conflict', mineLines, baseLines, theirsLines }
}

/**
 * Computes the ordered list of merge segments: stable runs of base lines,
 * runs resolved to one side (or to both, when they made the same change),
 * and conflicts where both sides changed the same region differently.
 *
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 * @returns {({kind: 'stable'|'mine'|'theirs'|'both', lines: string[]}
 *   | {kind: 'conflict', mineLines: string[], baseLines: string[], theirsLines: string[]})[]}
 */
export function mergeDocuments(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine)
  const theirsChanges = computeChanges(base, theirs)
  const regions = buildRegions(mineChanges, theirsChanges)

  const segments = []
  let prevEnd = 0
  for (const region of regions) {
    if (region.baseStart > prevEnd) {
      segments.push({ kind: 'stable', lines: base.slice(prevEnd, region.baseStart) })
    }
    const resolved = resolveRegion(region, base, mine, theirs)
    if (resolved.type === 'conflict') {
      segments.push({
        kind: 'conflict',
        mineLines: resolved.mineLines,
        baseLines: resolved.baseLines,
        theirsLines: resolved.theirsLines,
      })
    } else {
      segments.push({ kind: resolved.type, lines: resolved.lines })
    }
    prevEnd = region.baseEnd
  }
  if (prevEnd < base.length) {
    segments.push({ kind: 'stable', lines: base.slice(prevEnd, base.length) })
  }
  return segments
}
