 * Splits raw stdin text into the three documents (mine, base, theirs)
 * separated by lines that are exactly `%%%`.
 *
 * @param {string} input
 * @returns {string[][] | null} the three documents, or null when the input
 *   does not hold exactly three parts.
 */
export function parseDocuments(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      docs.push([])
    } else {
      docs[docs.length - 1].push(line)
    }
  }
  if (docs.length !== 3) return null
  return docs
}
"}

