/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */
import { readFileSync } from 'node:fs'
import { parseDocuments } from './parse.js'
import { mergeDocuments } from './merge.js'
import { render } from './render.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

const mode = process.argv[2]
if (process.argv.length !== 3 || !MODES.includes(mode)) {
  fail('error: usage: cli.js merge|merge2|regions')
}

const input = readFileSync(0, 'utf8')
const docs = parseDocuments(input)
if (docs === null) {
  fail('error: expected three parts separated by %%%')
}

const [mine, base, theirs] = docs
const segments = mergeDocuments(mine, base, theirs)
const { lines, hasConflict } = render(segments, mode)

process.stdout.write(lines.map(line => `${line}\n`).join(''))
process.exit(hasConflict ? 1 : 0)
"}

